// IPv4 subnet calculator — the same arithmetic routers use
function ipToInt(ip) {
  return ip.split('.').reduce((acc, octet) => (acc << 8) | parseInt(octet, 10), 0) >>> 0;
}

function intToIp(n) {
  return [
    (n >>> 24) & 0xff,
    (n >>> 16) & 0xff,
    (n >>>  8) & 0xff,
     n         & 0xff
  ].join('.');
}

function subnetInfo(cidr) {
  const [ip, prefixStr] = cidr.split('/');
  const prefix  = parseInt(prefixStr, 10);
  // Build the mask: shift 32-prefix zeros into the low bits
  const mask    = prefix === 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0;
  const ipInt   = ipToInt(ip);
  const network = (ipInt & mask) >>> 0;
  const bcast   = (network | (~mask >>> 0)) >>> 0;
  const hosts   = prefix <= 30 ? Math.pow(2, 32 - prefix) - 2
                : prefix === 31 ? 2   // RFC 3021 point-to-point
                : 1;                  // /32 host route
  return {
    network:   intToIp(network),
    broadcast: intToIp(bcast),
    mask:      intToIp(mask),
    firstHost: intToIp(network + 1),
    lastHost:  intToIp(bcast - 1),
    hostCount: hosts
  };
}

console.log(subnetInfo('192.168.1.42/24'));
// { network: '192.168.1.0', broadcast: '192.168.1.255',
//   mask: '255.255.255.0', firstHost: '192.168.1.1',
//   lastHost: '192.168.1.254', hostCount: 254 }

console.log(subnetInfo('10.0.0.0/8'));
// { network: '10.0.0.0', broadcast: '10.255.255.255',
//   mask: '255.0.0.0', firstHost: '10.0.0.1',
//   lastHost: '10.255.255.254', hostCount: 16777214 }

console.log(subnetInfo('10.1.2.3/30'));
// hostCount: 2  — classic point-to-point link

// Check whether two hosts are in the same subnet
function sameSubnet(ip1, ip2, prefix) {
  const mask = (0xffffffff << (32 - prefix)) >>> 0;
  return (ipToInt(ip1) & mask) === (ipToInt(ip2) & mask);
}
console.log(sameSubnet('192.168.1.5', '192.168.1.200', 24)); // true
console.log(sameSubnet('192.168.1.5', '192.168.2.5',   24)); // false

// Simulate longest-prefix matching — the core router algorithm
function longestPrefixMatch(destIp, routingTable) {
  const destInt = ipToInt(destIp);
  let bestRoute = null;
  let bestLen   = -1;
  for (const route of routingTable) {
    const [network, prefixStr] = route.cidr.split('/');
    const prefix = parseInt(prefixStr, 10);
    const mask   = prefix === 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0;
    if ((destInt & mask) >>> 0 === ipToInt(network) >>> 0) {
      if (prefix > bestLen) { bestLen = prefix; bestRoute = route; }
    }
  }
  return bestRoute;
}

const table = [
  { cidr: '0.0.0.0/0',    nexthop: '10.0.0.1',  iface: 'eth0' }, // default
  { cidr: '10.0.0.0/8',   nexthop: '10.0.0.2',  iface: 'eth1' },
  { cidr: '10.0.1.0/24',  nexthop: '10.0.0.3',  iface: 'eth2' }, // more specific
];
console.log(longestPrefixMatch('10.0.1.15', table));
// { cidr: '10.0.1.0/24', nexthop: '10.0.0.3', iface: 'eth2' }  <- chosen
console.log(longestPrefixMatch('10.0.2.5', table));
// { cidr: '10.0.0.0/8',  nexthop: '10.0.0.2', iface: 'eth1' }  <- /8 wins

// CIDR toolkit: subnetting, supernetting, and IPv6 exploration

// ── CIDR prefix → host count table ───────────────────────────
const prefixTable = [];
for (let prefix = 8; prefix <= 32; prefix++) {
  let hosts;
  if      (prefix < 31)  hosts = Math.pow(2, 32 - prefix) - 2;
  else if (prefix === 31) hosts = 2;   // RFC 3021 point-to-point
  else                    hosts = 1;   // /32 host route
  prefixTable.push({ prefix: `/${prefix}`, hosts, mask: prefixToMask(prefix) });
}

function prefixToMask(prefix) {
  const n = prefix === 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0;
  return [(n>>>24)&0xff, (n>>>16)&0xff, (n>>>8)&0xff, n&0xff].join('.');
}

console.table(prefixTable.filter(r => [8,16,24,25,28,30,31,32].includes(parseInt(r.prefix))));
// /8   → 16,777,214  hosts  mask: 255.0.0.0
// /16  → 65,534      hosts  mask: 255.255.0.0
// /24  → 254         hosts  mask: 255.255.255.0
// /25  → 126         hosts  mask: 255.255.255.128
// /28  → 14          hosts  mask: 255.255.255.240
// /30  → 2           hosts  mask: 255.255.255.252  (point-to-point)
// /31  → 2           hosts  mask: 255.255.255.254  (RFC 3021 p2p)
// /32  → 1           host   mask: 255.255.255.255  (host route)

// ── Subnet a /24 into 4 equal /26 subnets ────────────────────
function splitSubnet(networkCidr, newPrefix) {
  const [base, oldPrefixStr] = networkCidr.split('/');
  const oldPrefix = parseInt(oldPrefixStr);
  if (newPrefix <= oldPrefix) throw new Error('new prefix must be longer');
  const subnetCount = Math.pow(2, newPrefix - oldPrefix);
  const ipToInt = ip => ip.split('.').reduce((a, o) => (a << 8) | parseInt(o), 0) >>> 0;
  const intToIp = n => [(n>>>24)&0xff,(n>>>16)&0xff,(n>>>8)&0xff,n&0xff].join('.');
  const hostBits = 32 - newPrefix;
  const baseInt  = ipToInt(base);
  return Array.from({ length: subnetCount }, (_, i) => {
    const start = (baseInt + i * Math.pow(2, hostBits)) >>> 0;
    return intToIp(start) + '/' + newPrefix;
  });
}

console.log(splitSubnet('192.168.1.0/24', 26));
// ['192.168.1.0/26', '192.168.1.64/26', '192.168.1.128/26', '192.168.1.192/26']

